/*
 * Run The Floor: build hoops/career.js from its parts in hoops/career/.
 *
 *   node hoops/build/career-bundle.mjs           write hoops/career.js
 *   node hoops/build/career-bundle.mjs --check   fail if hoops/career.js is not its parts
 *
 * Career is one closure: every part shares one scope, the way the single file
 * always did, so a name in one part is read in another with no import and no
 * prefix. The page and every check keep loading the one built file, with its
 * one ?v=, which is why this is a join and not a module system. The parts are
 * the source. A part is plain declarations in the closure's order: a constant a
 * later part reads at load time has to be in an earlier part, the same rule as
 * reading it further down one file.
 *
 * After editing a part: run this, bump career.js?v= in hoops/index.html, then
 * node scripts/check-cachebust.mjs --update. hoops-checks runs --check.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const DIR = path.join(HERE, '..', 'career');
const OUT = path.join(HERE, '..', 'career.js');

/* The order is the closure's order. Every file in the folder is listed, and a
   file nobody listed fails, so a new part cannot be left out of the build. */
const PARTS = [
  'about',         // what Career is, and the shape of a year (comments only)
  'tuning',        // every balance number, first so any part may read one at load
  'basics',        // the league's clubs list, the player: positions, ratings, archetypes, sizes; small helpers
  'league',        // club strength, name pools, the coaching carousel, the rosters, the front office
  'people',        // who a line is about: the locker room, the tokens, say()
  'life',          // a new life, the save and how an old one is brought forward
  'season',        // draft night, a season, the awards, the playoffs and moments, the offseason, the legacy
  'events',        // the NBA event catalog, the press room, the people around you, milestones
  'club',          // the bench and your role, the trade deadline, the summer
  'story-engine',  // the event schema, the narrator, continuity, memory and arcs, traits, the living league
  'amateur',       // high school and college, and their cards
  'story',         // the Phase D compiler, your club's cards, origins, routes, endings
  'stories',       // the authored storylines and epilogues: content only
  'turns',         // answering a card, the step machine, things to do between cards
  'api',           // what the page reads, the generated road, a son, the public object
];

const HEAD = `/* GENERATED: do not edit this file. It is built from the parts in
 * hoops/career/ by \`node hoops/build/career-bundle.mjs\`. Edit a part, run
 * that, then bump career.js?v= in hoops/index.html. hoops-checks fails when
 * this file and its parts disagree.
 */
'use strict';
(function() {

`;
const TAIL = `})();
`;

const onDisk = fs.readdirSync(DIR).filter((f) => f.endsWith('.js')).map((f) => f.slice(0, -3)).sort();
const unlisted = onDisk.filter((f) => !PARTS.includes(f));
const missing = PARTS.filter((f) => !onDisk.includes(f));
if (unlisted.length || missing.length) {
  console.error('hoops/career/ and the part list disagree: ' +
    (unlisted.length ? 'not listed ' + unlisted.join(', ') + '. ' : '') +
    (missing.length ? 'missing ' + missing.join(', ') + '.' : ''));
  process.exit(1);
}

const built = HEAD + PARTS.map((p) => fs.readFileSync(path.join(DIR, p + '.js'), 'utf8').replace(/\n*$/, '\n')).join('\n') + TAIL;

if (process.argv.includes('--check')) {
  const now = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
  if (now !== built) {
    console.error('hoops/career.js is not its parts. Edit hoops/career/, never career.js, then run:\n' +
      '  node hoops/build/career-bundle.mjs');
    process.exit(1);
  }
  console.log(`career.js is its ${PARTS.length} parts`);
} else {
  fs.writeFileSync(OUT, built);
  console.log(`wrote hoops/career.js from ${PARTS.length} parts (${built.split('\n').length} lines)`);
}
